reply:
```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment> a owl:Ontology ;
    rdfs:label "Educational Assessment Ontology" ;
    rdfs:comment "Models classification claims about educational assessment, testing, validity, reliability and related concepts as stated in the source corpus. Where the corpus presents conflicting classification schemes (coordinate vs. subordinate), both are encoded and the tension is noted in rdfs:comment." .

############################################
## CORE ASSESSMENT CLASS
############################################

ea:Assessment a owl:Class ;
    rdfs:label "Assessment" ;
    skos:altLabel "educational assessment", "educational evaluation" ;
    rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning. NOTE: one corpus passage lists an 'Assessment types' enumeration (Formative, Summative, Norm-referenced test, Criterion-referenced test, Performance-based, Authentic, Standardized, Non-standardized, High-stakes, Competitive examination) as if these were coordinate siblings of a single taxonomy, even though this ontology models them as bridges across several orthogonal axes (purpose, reference, standardization, stakes). Both readings are preserved: the axis-based equivalentClass bridges below, and this comment documenting the corpus's flattened coordinate listing." .

ea:Examination a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Examination" ;
    skos:altLabel "test", "exam", "evaluation" ;
    rdfs:comment "An examination (exam, evaluation) or test is an educational assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification." .

ea:hasItem a owl:ObjectProperty ;
    rdfs:domain ea:Examination ;
    rdfs:range ea:TestItem ;
    rdfs:label "hasItem" .

ea:isItemOf a owl:ObjectProperty ;
    owl:inverseOf ea:hasItem ;
    rdfs:domain ea:TestItem ;
    rdfs:range ea:Examination .

ea:hasLearningOutcome a owl:ObjectProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:LearningOutcome ;
    rdfs:label "hasLearningOutcome" .

ea:hasRubric a owl:ObjectProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:Rubric ;
    rdfs:label "hasRubric" .

############################################
## GRANULARITY AXIS
############################################

ea:GranularityCategory a owl:Class ;
    owl:disjointUnionOf ( ea:IndividualLearnerGranularity ea:LearningCommunityGranularity
                          ea:CourseGranularity ea:AcademicProgramGranularity
                          ea:InstitutionGranularity ea:EducationalSystemGranularity ) .

ea:IndividualLearnerGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:LearningCommunityGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:CourseGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:AcademicProgramGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:InstitutionGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:EducationalSystemGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:GranularityCategory .

############################################
## PURPOSE AXIS  (placement / formative / summative / diagnostic)
############################################

ea:PurposeCategory a owl:Class ;
    owl:disjointUnionOf ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:PurposeCategory .

ea:PlacementAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test", "TKT" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] .

ea:FormativeAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    skos:altLabel "formative evaluation", "formative feedback", "assessment for learning", "educative assessment", "classroom assessment" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] .

ea:SummativeAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    skos:altLabel "summative evaluation", "assessment of learning" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] .

ea:DiagnosticAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:subClassOf ea:FormativeAssessment ;
    rdfs:comment "TENSION: one passage lists diagnostic assessment as a fourth coordinate category alongside placement, formative and summative assessment ('Placement, formative, summative and diagnostic assessment'); another passage states 'A common form of formative assessment is diagnostic assessment', i.e. subordinates it under formative assessment. Both the coordinate PurposeCategory membership (ea:DiagnosticPurpose) and the rdfs:subClassOf ea:FormativeAssessment axiom are asserted." ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] .

ea:SelfAssessment a owl:Class ;
    rdfs:subClassOf ea:DiagnosticAssessment ;
    rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

ea:ForwardLookingAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

ea:ContinuousAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:comment "Evaluates a student's progress throughout a prescribed course; often includes formative assessment." .

[] a owl:AllDisjointClasses ;
    owl:members ( ea:PlacementAssessment ea:FormativeAssessment ea:SummativeAssessment ) .

############################################
## PERFORMANCE-BASED / AUTHENTIC ASSESSMENT
############################################

ea:PerformanceBasedAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    skos:altLabel "performance assessment" ;
    rdfs:comment "Similar to summative assessment in that it focuses on achievement; requires students to create, produce, or do something, often with real-world application." .

ea:OutcomeFormatCategory a owl:Class ;
    owl:disjointUnionOf ( ea:ProductOutcome ea:PerformanceOutcome ) .

ea:ProductOutcome a owl:Class ; rdfs:subClassOf ea:OutcomeFormatCategory ;
    rdfs:comment "E.g. a painting, portfolio, paper, or exhibition." .
ea:PerformanceOutcome a owl:Class ; rdfs:subClassOf ea:OutcomeFormatCategory ;
    rdfs:comment "E.g. a speech, athletic skill, musical recital, or reading." .

ea:hasOutcomeFormat a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:PerformanceBasedAssessment ;
    rdfs:range ea:OutcomeFormatCategory .

ea:AssessmentContextCategory a owl:Class .
ea:RealWorldContext a owl:Class ; rdfs:subClassOf ea:AssessmentContextCategory .

ea:hasContext a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:AssessmentContextCategory .

ea:AuthenticAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasContext ; owl:someValuesFrom ea:RealWorldContext ] ) ] ;
    rdfs:comment "Measurement of accomplishments within a realistic, practical context relevant outside of the school setting; Glossary source states performance assessments 'may also be called authentic assessments'." .

############################################
## GLOSSARY PURPOSE TYPOLOGY (tension with PURPOSE AXIS above)
############################################

ea:PreAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:comment "TENSION: the Glossary of Education Reform lists 'Pre-assessments' as a coordinate assessment type distinct from 'Placement assessments', defined as establishing a baseline before a lesson/unit begins. This conflicts with the earlier passage which treats 'pre-assessment' as a mere synonym (altLabel) of ea:PlacementAssessment. Both are encoded: the altLabel on ea:PlacementAssessment, and this distinct coordinate class." .

ea:ScreeningAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:comment "Used to determine whether students may need specialized assistance/services or are ready to begin a course, grade level, or program." .

ea:InterimAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:comment "TENSION: used to evaluate progress toward future summative assessments; some educators consider interim assessments formative (diagnostic use), others consider them summative/distinct; the corpus notes ongoing debate about this classification." .

ea:CommonAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:comment "Used across a school/district for consistent evaluation; may be formative or summative." .

ea:PortfolioBasedAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    skos:altLabel "portfolio assessment" .

ea:StandardsBasedAssessment a owl:Class ;
    skos:altLabel "standards-based assessment" ;
    owl:equivalentClass ea:CriterionReferencedAssessment ;
    rdfs:comment "Criterion-referenced tests 'have also been called standards-based assessments' per the corpus." .

############################################
## OBJECTIVE / SUBJECTIVE AXIS
############################################

ea:ResponseTypeCategory a owl:Class ;
    owl:disjointUnionOf ( ea:ObjectiveResponseType ea:SubjectiveResponseType ) .

ea:ObjectiveResponseType a owl:Class ; rdfs:subClassOf ea:ResponseTypeCategory .
ea:SubjectiveResponseType a owl:Class ; rdfs:subClassOf ea:ResponseTypeCategory .

ea:hasResponseType a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:ResponseTypeCategory .

ea:ObjectiveAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:ObjectiveResponseType ] ) ] ;
    rdfs:comment "A form of questioning that has a single correct answer." .

ea:SubjectiveAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:SubjectiveResponseType ] ) ] ;
    rdfs:comment "A form of questioning that may have more than one correct answer." .

############################################
## TEST ITEM / QUESTION TYPES
############################################

ea:TestItem a owl:Class ;
    rdfs:label "TestItem" ;
    skos:altLabel "item", "question" .

ea:hasStem a owl:ObjectProperty ; rdfs:domain ea:MultipleChoiceQuestion .
ea:hasOption a owl:ObjectProperty ; rdfs:domain ea:MultipleChoiceQuestion .
ea:hasKey a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:MultipleChoiceQuestion ;
    rdfs:comment "Only one answer may be keyed as correct for a multiple-choice item." .
ea:hasDistractor a owl:ObjectProperty ; rdfs:domain ea:MultipleChoiceQuestion .

ea:ObjectiveQuestion a owl:Class ;
    rdfs:subClassOf ea:TestItem ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
        [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:ObjectiveResponseType ] ) ] .

ea:SubjectiveQuestion a owl:Class ;
    rdfs:subClassOf ea:TestItem ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
        [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:SubjectiveResponseType ] ) ] .

ea:TrueFalseQuestion a owl:Class ; rdfs:subClassOf ea:ObjectiveQuestion .
ea:MultipleChoiceQuestion a owl:Class ; rdfs:subClassOf ea:ObjectiveQuestion ;
    skos:altLabel "MCQ", "multiple choice item", "objective response" .
ea:MultipleResponseQuestion a owl:Class ; rdfs:subClassOf ea:ObjectiveQuestion ;
    rdfs:comment "Unlike multiple-choice items, more than one answer may be keyed as correct." .
ea:MatchingQuestion a owl:Class ; rdfs:subClassOf ea:ObjectiveQuestion .

[] a owl:AllDisjointClasses ;
    owl:members ( ea:TrueFalseQuestion ea:MultipleChoiceQuestion ea:MultipleResponseQuestion ea:MatchingQuestion ) .

ea:ExtendedResponseQuestion a owl:Class ; rdfs:subClassOf ea:SubjectiveQuestion .
ea:EssayQuestion a owl:Class ; rdfs:subClassOf ea:SubjectiveQuestion ;
    skos:altLabel "free response question", "FRQ" ;
    rdfs:comment "A free response question (FRQ) or essay question is a type of open-ended question requiring a prose response." .

[] a owl:AllDisjointClasses ;
    owl:members ( ea:ExtendedResponseQuestion ea:EssayQuestion ) .

owl:disjointWith ea:ObjectiveQuestion .

ea:TrueFalseFamilyQuestion a owl:Class ;
    rdfs:subClassOf ea:MultipleChoiceQuestion ;
    rdfs:comment "TENSION: the corpus states there are 'two families of multiple-choice questions': a True/False family (choose all appropriate answers) and a One-Best-Answer family, subordinating 'true/false' under multiple-choice. This conflicts with the earlier passage listing true/false and multiple-choice as coordinate, disjoint objective question types (ea:TrueFalseQuestion vs ea:MultipleChoiceQuestion). Both are encoded." .

ea:OneBestAnswerQuestion a owl:Class ;
    rdfs:subClassOf ea:MultipleChoiceQuestion .

ea:FillInTheBlankQuestion a owl:Class ;
    rdfs:subClassOf ea:TestItem .

ea:ShortAnswerQuestion a owl:Class ;
    rdfs:subClassOf ea:TestItem ;
    rdfs:comment "Grouped with essay items as requiring the test taker to write a response." .

ea:MathQuestion a owl:Class ;
    rdfs:subClassOf ea:TestItem ;
    rdfs:comment "Mathematics/calculation-style questions requiring a freehand response; marks given for steps as well as final answer." .

############################################
## ADMINISTRATION MODE AXIS (written / oral / practical)
############################################

ea:AdministrationModeCategory a owl:Class ;
    owl:disjointUnionOf ( ea:WrittenMode ea:OralMode ea:PracticalMode ) .

ea:WrittenMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:OralMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:PracticalMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .

ea:hasAdministrationMode a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Examination ;
    rdfs:range ea:AdministrationModeCategory .

ea:WrittenTest a owl:Class ;
    rdfs:subClassOf ea:Examination ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Examination
        [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:WrittenMode ] ) ] .

ea:PerformanceTest a owl:Class ;
    rdfs:subClassOf ea:Examination ;
    skos:altLabel "work sample" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Examination
        [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:PracticalMode ] ) ] ;
    rdfs:comment "Requires an examinee to actually perform a task or activity rather than answer questions about it." .

############################################
## STANDARDIZATION AXIS
############################################

ea:StandardizationCategory a owl:Class ;
    owl:disjointUnionOf ( ea:StandardizedCategory ea:NonStandardizedCategory ) .

ea:StandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .

ea:hasStandardizationStatus a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Examination ;
    rdfs:range ea:StandardizationCategory .

ea:StandardizedTest a owl:Class ;
    rdfs:subClassOf ea:Examination ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Examination
        [ a owl:Restriction ; owl:onProperty ea:hasStandardizationStatus ; owl:someValuesFrom ea:StandardizedCategory ] ) ] ;
    rdfs:comment "Administered and scored in a consistent, predetermined manner for all test takers." .

ea:NonStandardizedTest a owl:Class ;
    rdfs:subClassOf ea:Examination ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Examination
        [ a owl:Restriction ; owl:onProperty ea:hasStandardizationStatus ; owl:someValuesFrom ea:NonStandardizedCategory ] ) ] .

ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:AptitudeTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:CollegeAdmissionsTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .

[] a owl:AllDisjointClasses ;
    owl:members ( ea:AchievementTest ea:AptitudeTest ea:CollegeAdmissionsTest
                  ea:InternationalComparisonTest ea:PsychologicalTest ) .

############################################
## STAKES AXIS
############################################

ea:StakesCategory a owl:Class ;
    owl:disjointUnionOf ( ea:HighStakesCategory ea:LowStakesCategory ) .

ea:HighStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .

ea:hasStakesLevel a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:StakesCategory .

ea:HighStakesTest a owl:Class ;
    rdfs:subClassOf ea:Examination ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Examination
        [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
    rdfs:comment "A test with a desired reward for good performance; important consequences for students, educators, schools, or districts." .

ea:LowStakesTest a owl:Class ;
    rdfs:subClassOf ea:Examination ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Examination
        [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:LowStakesCategory ] ) ] .

############################################
## REFERENCING AXIS (criterion / norm / ipsative)
############################################

ea:ReferenceCategory a owl:Class ;
    owl:disjointUnionOf ( ea:CriterionReference ea:NormReference ea:IpsativeReference ) ;
    rdfs:comment "TENSION: the corpus elsewhere states 'There are two types of test score interpretations' (norm-referenced and criterion-referenced), omitting ipsative referencing from that duo, while the general 'referencing' classification treats criterion-, norm- and ipsative-referencing as three coordinate alternatives. Both readings are retained: this three-way disjoint union, and the fact that ea:hasScoreInterpretation/ea:hasReferenceType is reused without an ipsative value for score-interpretation contexts." .

ea:CriterionReference a owl:Class ; rdfs:subClassOf ea:ReferenceCategory .
ea:NormReference a owl:Class ; rdfs:subClassOf ea:ReferenceCategory .
ea:IpsativeReference a owl:Class ; rdfs:subClassOf ea:ReferenceCategory .

ea:hasReferenceType a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:ReferenceCategory .

ea:CriterionReferencedAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:CriterionReference ] ) ] .

ea:NormReferencedAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    skos:altLabel "normative assessment" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:NormReference ] ) ] .

ea:IpsativeAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:IpsativeReference ] ) ] ;
    rdfs:comment "Self-comparison either in the same domain over time, or comparative to other domains within the same student." .

[] a owl:AllDisjointClasses ;
    owl:members ( ea:CriterionReferencedAssessment ea:NormReferencedAssessment ea:IpsativeAssessment ) .

ea:CriterionReferencedTest a owl:Class ;
    skos:altLabel "CRT" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Examination ea:CriterionReferencedAssessment ) ] .

ea:NormReferencedTest a owl:Class ;
    skos:altLabel "NRT" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Examination ea:NormReferencedAssessment ) ] .

ea:NormGroup a owl:Class ;
    skos:altLabel "norming group" ;
    rdfs:comment "The comparison group derived from a sample used to estimate a tested individual's relative position." .

ea:hasNormGroup a owl:ObjectProperty ;
    rdfs:domain ea:NormReferencedTest ;
    rdfs:range ea:NormGroup .

ea:hasCutScore a owl:DatatypeProperty ;
    rdfs:domain ea:CriterionReferencedAssessment ;
    rdfs:range xsd:decimal .

############################################
## FORMALITY AXIS
############################################

ea:FormalityCategory a owl:Class ;
    owl:disjointUnionOf ( ea:FormalCategory ea:InformalCategory ) .

ea:FormalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:FormalityCategory .

ea:FormalAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalCategory ] ) ] ;
    rdfs:comment "Usually implies a written document and is given a numerical score or grade." .

ea:InformalAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalCategory ] ) ] ;
    rdfs:comment "Does not contribute to a student's final grade." .

############################################
## ADMINISTRATION SCOPE AXIS (internal / external)
############################################

ea:AdministrationScopeCategory a owl:Class ;
    owl:disjointUnionOf ( ea:InternalCategory ea:ExternalCategory ) .

ea:InternalCategory a owl:Class ; rdfs:subClassOf ea:AdministrationScopeCategory .
ea:ExternalCategory a owl:Class ; rdfs:subClassOf ea:AdministrationScopeCategory .

ea:hasAdministrationScope a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:AdministrationScopeCategory .

ea:InternalAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasAdministrationScope ; owl:someValuesFrom ea:InternalCategory ] ) ] ;
    rdfs:comment "Set and marked by the school (teachers)." .

ea:ExternalAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasAdministrationScope ; owl:someValuesFrom ea:ExternalCategory ] ) ] ;
    rdfs:comment "Set by a governing body and marked by unbiased personnel." .

############################################
## SPECIFIC EXAMINATION KINDS
############################################

ea:MidtermExam a owl:Class ;
    rdfs:subClassOf ea:Examination ;
    rdfs:subClassOf [ owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
    rdfs:comment "Given near the middle of an academic term; a type of formative or summative assessment." .

ea:FinalExam a owl:Class ;
    rdfs:subClassOf ea:Examination ;
    rdfs:subClassOf ea:SummativeAssessment ;
    skos:altLabel "final" .

ea:Quiz a owl:Class ;
    rdfs:subClassOf ea:Examination ;
    rdfs:subClassOf ea:FormativeAssessment ;
    rdfs:comment "A brief assessment; instructors usually provide this as a formative assessment." .

ea:CompetitiveExamination a owl:Class ;
    rdfs:subClassOf ea:Examination ;
    owl:equivalentClass [ owl:intersectionOf (
        ea:Examination
        [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:NormReference ]
        [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:HighStakesCategory ]
    ) ] ;
    rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and top rankers selected." .

############################################
## VALIDITY
############################################

ea:ValidityEvidence a owl:Class ;
    rdfs:label "ValidityEvidence" ;
    rdfs:comment "TENSION: one passage enumerates content, criterion and construct validity (plus consequential and face validity) as coordinate categories of evidence, which is modeled here via disjointUnionOf. Another passage states construct validity 'subsumes all other types of validity' and that modern theory treats it as 'the overarching concern of validity research, subsuming all other types of validity evidence such as content validity and criterion validity' -- modeled via explicit rdfs:subClassOf axioms below. Both are asserted even though jointly they are inconsistent with strict disjointness." ;
    owl:disjointUnionOf ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity ea:FaceValidity ea:ConsequentialValidity ) .

ea:ContentValidity a owl:Class ;
    rdfs:subClassOf ea:ValidityEvidence ;
    skos:altLabel "logical validity" ;
    rdfs:subClassOf ea:ConstructValidity ;
    rdfs:comment "Per the subsumption claim, content validity is also modeled as a subclass of construct validity." .

ea:CriterionValidity a owl:Class ;
    rdfs:subClassOf ea:ValidityEvidence ;
    skos:altLabel "criterion-related validity" ;
    rdfs:subClassOf ea:ConstructValidity ;
    rdfs:comment "Per the subsumption claim, criterion validity is also modeled as a subclass of construct validity." .

ea:ConstructValidity a owl:Class ;
    rdfs:subClassOf ea:ValidityEvidence ;
    rdfs:comment "Refers to the extent to which operationalizations of a construct measure the construct as defined by theory. States of the corpus: 'It subsumes all other types of validity.'" .

ea:FaceValidity a owl:Class ;
    rdfs:subClassOf ea:ValidityEvidence ;
    rdfs:subClassOf ea:ConstructValidity .

ea:ConsequentialValidity a owl:Class ;
    rdfs:subClassOf ea:ValidityEvidence .

ea:SubjectMatterValidity a owl:Class ;
    rdfs:subClassOf ea:ValidityEvidence ;
    rdfs:comment "Widely used in education; predicts the score a student would get on a similar test with different questions. Distinguished from 'predictive' validity used widely in the workplace." .

ea:ValidityTimingCategory a owl:Class ;
    owl:disjointUnionOf ( ea:ConcurrentTiming ea:PredictiveTiming ) .

ea:ConcurrentTiming a owl:Class ; rdfs:subClassOf ea:ValidityTimingCategory .
ea:PredictiveTiming a owl:Class ; rdfs:subClassOf ea:ValidityTimingCategory .

ea:hasValidityTiming a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:CriterionValidity ;
    rdfs:range ea:ValidityTimingCategory .

ea:ConcurrentValidity a owl:Class ;
    rdfs:subClassOf ea:CriterionValidity ;
    owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
        [ a owl:Restriction ; owl:onProperty ea:hasValidityTiming ; owl:someValuesFrom ea:ConcurrentTiming ] ) ] ;
    rdfs:comment "Comparison between test and criterion measured at the same time." .

ea:PredictiveValidity a owl:Class ;
    rdfs:subClassOf ea:CriterionValidity ;
    owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
        [ a owl:Restriction ; owl:onProperty ea:hasValidityTiming ; owl:someValuesFrom ea:PredictiveTiming ] ) ] ;
    rdfs:comment "Test data collected first, criterion data collected later." .

[] a owl:AllDisjointClasses ;
    owl:members ( ea:ConcurrentValidity ea:PredictiveValidity ) .

ea:ConvergentValidity a owl:Class ;
    rdfs:subClassOf ea:ConstructValidity ;
    rdfs:comment "Degree to which two measures of theoretically related constructs are in fact related." .

ea:DiscriminantValidity a owl:Class ;
    rdfs:subClassOf ea:ConstructValidity ;
    skos:altLabel "divergent validity" ;
    rdfs:comment "Tests whether concepts/measurements supposed to be unrelated are, in fact, unrelated." .

[] a owl:AllDisjointClasses ;
    owl:members ( ea:ConvergentValidity ea:DiscriminantValidity ) .

############################################
## RELIABILITY
############################################

ea:Reliability a owl:Class ;
    rdfs:label "Reliability" ;
    rdfs:comment "The consistency of an assessment; freedom of a measure from measurement error." .

ea:hasReliabilityCoefficient a owl:DatatypeProperty ;
    rdfs:domain ea:Reliability ;
    rdfs:range xsd:decimal .

ea:ReliabilityEstimate a owl:Class ;
    rdfs:subClassOf ea:Reliability ;
    rdfs:comment "There are 'several general classes of reliability estimates'." ;
    owl:disjointUnionOf ( ea:InterRaterReliability ea:TestRetestReliability
                          ea:InterMethodReliability ea:InternalConsistencyReliability ) .

ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimate ;
    rdfs:comment "Degree of agreement between two or more raters." .
ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimate ;
    skos:altLabel "repeatability", "temporal stability" ;
    rdfs:comment "Consistency of test scores from one administration to the next (includes intra-rater reliability)." .
ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimate ;
    skos:altLabel "parallel-forms reliability", "form equivalence" ;
    rdfs:comment "Consistency of test scores when there is variation in methods or instruments used." .
ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimate ;
    rdfs:comment "Consistency of results across items within a test." .

ea:ReliabilityErrorSource a owl:Class ;
    rdfs:subClassOf ea:Reliability ;
    rdfs:comment "TENSION: the corpus separately states 'There are four types of reliability: student-related, rater-related, test administration-related, and test-related', which is a different four-part typology from the 'general classes of reliability estimates' above (inter-rater, test-retest, inter-method, internal-consistency). Both typologies are encoded as distinct disjoint partitions under ea:Reliability." ;
    owl:disjointUnionOf ( ea:StudentRelatedReliabilityFactor ea:RaterRelatedReliabilityFactor
                          ea:TestAdministrationRelatedReliabilityFactor ea:TestRelatedReliabilityFactor ) .

ea:StudentRelatedReliabilityFactor a owl:Class ; rdfs:subClassOf ea:ReliabilityErrorSource .
ea:RaterRelatedReliabilityFactor a owl:Class ; rdfs:subClassOf ea:ReliabilityErrorSource .
ea:TestAdministrationRelatedReliabilityFactor a owl:Class ; rdfs:subClassOf ea:ReliabilityErrorSource .
ea:TestRelatedReliabilityFactor a owl:Class ; rdfs:subClassOf ea:ReliabilityErrorSource .

############################################
## RUBRIC
############################################

ea:Rubric a owl:Class ;
    rdfs:label "Rubric" ;
    skos:altLabel "scoring guide" ;
    rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses." .

ea:hasItemCount a owl:DatatypeProperty ;
    rdfs:domain ea:Examination ;
    rdfs:range xsd:integer .

ea:RubricTypeCategory a owl:Class ;
    owl:disjointUnionOf ( ea:HolisticRubricType ea:AnalyticRubricType ea:DevelopmentalRubricType ) .

ea:HolisticRubricType a owl:Class ; rdfs:subClassOf ea:RubricTypeCategory .
ea:AnalyticRubricType a owl:Class ; rdfs:subClassOf ea:RubricTypeCategory .
ea:DevelopmentalRubricType a owl:Class ; rdfs:subClassOf ea:RubricTypeCategory .

ea:hasRubricType a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Rubric ;
    rdfs:range ea:RubricTypeCategory .

ea:HolisticRubric a owl:Class ;
    rdfs:subClassOf ea:Rubric ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
        [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:HolisticRubricType ] ) ] ;
    rdfs:comment "Provides an overall rating for a piece of work considering all aspects." .

ea:AnalyticRubric a owl:Class ;
    rdfs:subClassOf ea:Rubric ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
        [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:AnalyticRubricType ] ) ] ;
    rdfs:comment "Evaluates various dimensions or components separately." .

ea:DevelopmentalRubric a owl:Class ;
    rdfs:subClassOf ea:Rubric ;
    rdfs:subClassOf ea:AnalyticRubric ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
        [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:DevelopmentalRubricType ] ) ] ;
    rdfs:comment "TENSION: 'Rubrics can be classified as holistic, analytic, or developmental' presents developmental rubrics as a coordinate third kind, while the same passage also states 'Developmental rubrics, a subset of analytical rubrics...'. Both the disjoint-union coordinate membership and the rdfs:subClassOf ea:AnalyticRubric axiom are asserted." .

############################################
## GRADING METHOD (holistic vs analytic grading / trait-informed scoring)
############################################

ea:GradingMethod a owl:Class ;
    rdfs:label "GradingMethod" .

ea:HolisticGrading a owl:Class ;
    rdfs:subClassOf ea:GradingMethod ;
    skos:altLabel "holistic scoring", "nonreductionist grading", "non-analytic", "overall quality", "general merit", "general impression", "rapid impression" ;
    owl:disjointWith ea:AnalyticGrading ;
    rdfs:comment "Bases a grade on a paper's overall quality; contrasts with analytic grading." .

ea:AnalyticGrading a owl:Class ;
    rdfs:subClassOf ea:GradingMethod ;
    rdfs:comment "Takes more factors into account when assigning a grade, judging criterion-by-criterion." .

ea:TraitInformedScoring a owl:Class ;
    rdfs:subClassOf ea:HolisticGrading ;
    rdfs:comment "Trains raters to score against a rubric with multiple criteria; 'comes close to analytic scoring methods' yet 'remains holistic at heart' -- noted tension between its closeness to analytic scoring and its classification here as a subclass of holistic grading." .

############################################
## FEEDBACK
############################################

ea:Feedback a owl:Class ;
    rdfs:label "Feedback" .

ea:CorrectiveFeedback a owl:Class ;
    rdfs:subClassOf ea:Feedback ;
    rdfs:comment "Formal or informal feedback on understanding or performance that is nonevaluative, supportive, timely, and specific." .

ea:Recast a owl:Class ;
    rdfs:subClassOf ea:CorrectiveFeedback ;
    rdfs:comment "A subtle correction of a young child's spoken errors, typically by a parent or caregiver." .

############################################
## LEARNING OUTCOME
############################################

ea:LearningOutcome a owl:Class ;
    rdfs:label "LearningOutcome" ;
    owl:disjointUnionOf ( ea:IntendedLearningOutcome ea:MeasuredLearningOutcome ea:UnintendedLearningOutcome ) .

ea:IntendedLearningOutcome a owl:Class ;
    rdfs:subClassOf ea:LearningOutcome ;
    skos:altLabel "aim" .

ea:MeasuredLearningOutcome a owl:Class ;
    rdfs:subClassOf ea:LearningOutcome ;
    skos:altLabel "objective" .

ea:UnintendedLearningOutcome a owl:Class ;
    rdfs:subClassOf ea:LearningOutcome ;
    rdfs:comment "Beneficial outcomes that were neither planned nor sought but are simply observed." .

ea:LearningOutcomeTaxonomy a owl:Class ;
    rdfs:label "LearningOutcomeTaxonomy" ;
    owl:disjointUnionOf ( ea:BloomsTaxonomy ea:StructureOfObservedLearningOutcome
                          ea:DikwPyramid ea:ModelOfHierarchicalComplexity ) .

ea:BloomsTaxonomy a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:StructureOfObservedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy ; skos:altLabel "SOLO" .
ea:DikwPyramid a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy ; skos:altLabel "DIKW pyramid" .
ea:ModelOfHierarchicalComplexity a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .

############################################
## TRANSFER OF LEARNING
############################################

ea:TransferOfLearning a owl:Class ;
    rdfs:label "TransferOfLearning" .

ea:TransferDistanceCategory a owl:Class ;
    owl:disjointUnionOf ( ea:NearTransferDistance ea:FarTransferDistance ) .
ea:NearTransferDistance a owl:Class ; rdfs:subClassOf ea:TransferDistanceCategory .
ea:FarTransferDistance a owl:Class ; rdfs:subClassOf ea:TransferDistanceCategory .

ea:hasTransferDistance a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:TransferOfLearning ;
    rdfs:range ea:TransferDistanceCategory .

ea:NearTransfer a owl:Class ;
    rdfs:subClassOf ea:TransferOfLearning ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
        [ a owl:Restriction ; owl:onProperty ea:hasTransferDistance ; owl:someValuesFrom ea:NearTransferDistance ] ) ] .

ea:FarTransfer a owl:Class ;
    rdfs:subClassOf ea:TransferOfLearning ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
        [ a owl:Restriction ; owl:onProperty ea:hasTransferDistance ; owl:someValuesFrom ea:FarTransferDistance ] ) ] .

ea:TransferEffectCategory a owl:Class ;
    owl:disjointUnionOf ( ea:PositiveTransferEffect ea:NegativeTransferEffect ) .
ea:PositiveTransferEffect a owl:Class ; rdfs:subClassOf ea:TransferEffectCategory .
ea:NegativeTransferEffect a owl:Class ; rdfs:subClassOf ea:TransferEffectCategory .

ea:hasTransferEffect a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:TransferOfLearning ;
    rdfs:range ea:TransferEffectCategory .

ea:PositiveTransfer a owl:Class ;
    rdfs:subClassOf ea:TransferOfLearning ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
        [ a owl:Restriction ; owl:onProperty ea:hasTransferEffect ; owl:someValuesFrom ea:PositiveTransferEffect ] ) ] .

ea:NegativeTransfer a owl:Class ;
    rdfs:subClassOf ea:TransferOfLearning ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
        [ a owl:Restriction ; owl:onProperty ea:hasTransferEffect ; owl:someValuesFrom ea:NegativeTransferEffect ] ) ] .

############################################
## LEARNING TYPES (formal / non-formal / informal)
############################################

ea:Learning a owl:Class ;
    rdfs:label "Learning" .

ea:FormalLearning a owl:Class ; rdfs:subClassOf ea:Learning .
ea:NonFormalLearning a owl:Class ;
    rdfs:subClassOf ea:Learning ;
    rdfs:comment "Organized learning outside the formal learning system." .
ea:InformalLearning a owl:Class ;
    rdfs:subClassOf ea:Learning ;
    rdfs:comment "Less structured than non-formal learning; occurs through day-to-day experience." .

[] a owl:AllDisjointClasses ;
    owl:members ( ea:FormalLearning ea:NonFormalLearning ea:InformalLearning ) .

############################################
## PROFICIENCY / COMPETENCY-BASED LEARNING
############################################

ea:Proficiency a owl:Class ;
    rdfs:label "Proficiency" ;
    rdfs:comment "A determination based on standards or a measurement system; students demonstrate or fail to demonstrate proficiency in relation to learning standards." .

ea:CompetencyBasedLearning a owl:Class ;
    rdfs:label "CompetencyBasedLearning" ;
    skos:altLabel "proficiency-based learning", "mastery-based learning", "outcome-based learning", "performance-based learning", "standards-based learning" ;
    rdfs:comment "Systems of instruction, assessment, grading and reporting based on students demonstrating learned knowledge and skills." .

############################################
## PORTFOLIO
############################################

ea:StudentPortfolio a owl:Class ;
    rdfs:label "StudentPortfolio" ;
    skos:altLabel "digital portfolio", "e-portfolio" ;
    rdfs:comment "A compilation of academic work and other educational evidence." .

ea:CapstonePortfolio a owl:Class ;
    rdfs:subClassOf ea:StudentPortfolio ;
    rdfs:comment "Features student work completed as part of a long-term, culminating project." .

############################################
## TEACHER / VALUE-ADDED MEASURES
############################################

ea:TeacherPerformanceMeasure a owl:Class ;
    rdfs:label "TeacherPerformanceMeasure" .

ea:ValueAddedMeasure a owl:Class ;
    rdfs:subClassOf ea:TeacherPerformanceMeasure ;
    skos:altLabel "growth measure" .

ea:StudentGrowthMeasure a owl:Class ;
    rdfs:subClassOf ea:TeacherPerformanceMeasure ;
    owl:disjointWith ea:ValueAddedMeasure ;
    rdfs:comment "A related but distinct method of using student test scores to quantify academic achievement and growth." .

############################################
## MEASUREMENT ERROR / SCORE INFLATION
############################################

ea:MeasurementError a owl:Class ;
    rdfs:label "MeasurementError" ;
    rdfs:comment "Either (1) the difference between what a test score indicates and a student's actual knowledge/abilities, or (2) errors introduced when collecting and calculating data-based reports." .

ea:ScoreInflation a owl:Class ;
    rdfs:label "ScoreInflation" ;
    rdfs:comment "Results when scores increase without a genuine improvement in learning." .

ea:TrueScore a owl:Class ;
    rdfs:comment "The replicable feature of the concept being measured; part of the observed score that would recur across measurement occasions absent error." .

ea:ObservedScore a owl:Class ;
    rdfs:comment "X = T + E, the observed test score composed of true score and measurement error." .
